// go-01 示例：零值、:= 作用域、切片描述符、数组复制、多返回值与 iota
//
// 环境：Go 1.22
// 运行：go run main.go
package main

import (
	"errors"
	"fmt"
)

type Level int

const (
	LevelInfo Level = iota
	LevelWarn
	LevelError
)

func (l Level) String() string {
	switch l {
	case LevelInfo:
		return "INFO"
	case LevelWarn:
		return "WARN"
	case LevelError:
		return "ERROR"
	default:
		return "UNKNOWN"
	}
}

// splitEven 返回偶数子切片；错误用 errors.New / fmt.Errorf 构造。
func splitEven(in []int) ([]int, error) {
	if len(in) == 0 {
		return nil, errors.New("splitEven: empty input")
	}
	out := make([]int, 0, len(in))
	for _, v := range in {
		if v < 0 {
			return nil, fmt.Errorf("splitEven: negative value %d", v)
		}
		if v%2 == 0 {
			out = append(out, v)
		}
	}
	return out, nil
}

// appendOne 演示「切片是值」：函数内的 append 不会改调用方的长度。
func appendOne(dst []int) []int {
	return append(dst, 99)
}

func main() {
	// 1. 零值：声明即拿到该类型的零值。
	var (
		s  string
		n  int
		b  bool
		p  *int
		m  map[string]int
		sl []int
	)
	fmt.Printf("zero: %q %d %v %v %v %v\n", s, n, b, p, m, sl)

	// nil map 可读不可写；nil slice 可以直接 append。
	fmt.Println("nil map read:", m["missing"])
	sl = append(sl, 1)
	fmt.Println("nil slice append:", sl, len(sl), cap(sl))

	// 2. := 的作用域：块内 err 是新变量，外层 err 永远是 nil。
	var err error
	{
		_, err := splitEven(nil)
		_ = err
	}
	fmt.Println("outer err after shadow:", err)

	// 3. 多返回值 + 错误分支。
	got, err := splitEven([]int{1, 2, 3, 4})
	if err != nil {
		fmt.Println("unexpected:", err)
	}
	fmt.Println("evens:", got, "len:", len(got), "cap:", cap(got))

	if _, err := splitEven([]int{2, -1}); err != nil {
		fmt.Println("error:", err)
	}

	// 4. 数组是值类型：赋值会整体复制。
	arr := [3]int{1, 2, 3}
	copied := arr
	copied[0] = 100
	fmt.Println("array:", arr, copied)

	// 5. 切片共享底层数组，但 append 可能换新数组。
	base := []int{1, 2, 3}
	view := base[:2]
	view = append(view, 9)
	fmt.Println("slice:", base, view, len(view), cap(view))

	// 6. 函数返回新切片，调用方原长度不变。
	short := []int{1}
	longer := appendOne(short)
	fmt.Println("append:", short, longer)

	// 7. iota：从 0 开始，每个 ConstSpec 递增。
	fmt.Println("levels:", LevelInfo, LevelWarn, LevelError)
}

// 输出：
// zero: "" 0 false <nil> map[] []
// nil map read: 0
// nil slice append: [1] 1 1
// outer err after shadow: <nil>
// evens: [2 4] len: 2 cap: 4
// error: splitEven: negative value -1
// array: [1 2 3] [100 2 3]
// slice: [1 2 9] [1 2 9] 3 3
// append: [1] [1 99]
// levels: INFO WARN ERROR

