// go-02 示例：扇入、关闭与 range、select 超时、close 语义
//
// 环境：Go 1.22
// 运行：go run main.go
package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

// gen 把 nums 送入 channel，发完由发送方关闭。
func gen(ctx context.Context, nums ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for _, n := range nums {
			select {
			case out <- n:
			case <-ctx.Done():
				return
			}
		}
	}()
	return out
}

// merge 扇入：所有输入关闭后再关闭输出。
func merge(ctx context.Context, chs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(len(chs))
	for _, ch := range chs {
		go func(ch <-chan int) {
			defer wg.Done()
			for {
				select {
				case v, ok := <-ch:
					if !ok {
						return
					}
					select {
					case out <- v:
					case <-ctx.Done():
						return
					}
				case <-ctx.Done():
					return
				}
			}
		}(ch)
	}
	go func() {
		wg.Wait()
		close(out)
	}()
	return out
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), time.Second)
	defer cancel()

	a := gen(ctx, 1, 2, 3)
	b := gen(ctx, 4, 5)
	total := 0
	for v := range merge(ctx, a, b) {
		total += v
	}
	fmt.Println("merged total:", total) // 15，顺序不固定

	// select + default：没有就绪 case 时立刻走 default。
	ch := make(chan int, 1)
	select {
	case v := <-ch:
		fmt.Println("got:", v)
	default:
		fmt.Println("no value ready")
	}

	// close 之后 range 立即结束，再接收得到零值与 false。
	closed := make(chan int, 1)
	closed <- 7
	close(closed)
	for v := range closed {
		fmt.Println("drained:", v)
	}
	v, ok := <-closed
	fmt.Println("after close:", v, ok) // 0 false
}

// 输出（两路输入交错到达，前两行的顺序不固定，总和固定）：
// merged total: 15
// no value ready
// drained: 7
// after close: 0 false

// go-03 示例：方法集、接口、%w 包装、errors.Is/As、defer 顺序
//
// 环境：Go 1.22
// 运行：go run main.go
package main

import (
	"errors"
	"fmt"
)

// ErrNegative 是哨兵错误，调用方用 errors.Is 判断。
var ErrNegative = errors.New("negative dimension")

// Shape 是消费方定义的小接口：只要一个 Area 方法。
type Shape interface {
	Area() float64
}

type Rect struct {
	W, H float64
}

// 指针接收者：方法集属于 *Rect，不属于 Rect。
func (r *Rect) Area() float64 {
	if r.W < 0 || r.H < 0 {
		return 0
	}
	return r.W * r.H
}

type Circle struct {
	R float64
}

// 值接收者：Circle 和 *Circle 都实现 Shape。
func (c Circle) Area() float64 {
	return 3.14159 * c.R * c.R
}

// DimensionError 是带上下文的类型化错误，调用方可用 errors.As 取出。
type DimensionError struct {
	Name  string
	Value float64
}

func (e *DimensionError) Error() string {
	return fmt.Sprintf("%s is %g", e.Name, e.Value)
}

func NewRect(w, h float64) (*Rect, error) {
	if w < 0 {
		return nil, fmt.Errorf("NewRect: width %w: %v", ErrNegative, w)
	}
	if h < 0 {
		return nil, fmt.Errorf("NewRect: height: %w", &DimensionError{Name: "height", Value: h})
	}
	return &Rect{W: w, H: h}, nil
}

func main() {
	_, err := NewRect(-1, 2)
	fmt.Println("err:", err)
	fmt.Println("errors.Is negative:", errors.Is(err, ErrNegative))

	_, err = NewRect(2, -3)
	fmt.Println("err:", err)
	fmt.Println("errors.Is negative:", errors.Is(err, ErrNegative))
	var de *DimensionError
	if errors.As(err, &de) {
		fmt.Println("as:", de.Name, de.Value)
	}

	// Rect 的 Area 是指针接收者，所以切片里放 *Rect。
	shapes := []Shape{&Rect{W: 2, H: 3}, Circle{R: 1}}
	for _, s := range shapes {
		fmt.Printf("%T area=%.2f\n", s, s.Area())
	}

	// defer 是 LIFO，参数在 defer 语句处就求值。
	x := 1
	defer fmt.Println("deferred x:", x) // 捕获 1
	x = 2
	defer func() { fmt.Println("closure x:", x) }() // 捕获变量，输出 2
	fmt.Println("body x:", x)
}

// 输出：
// err: NewRect: width negative dimension: -1
// errors.Is negative: true
// err: NewRect: height: height is -3
// errors.Is negative: false
// as: height -3
// *main.Rect area=6.00
// main.Circle area=3.14
// body x: 2
// closure x: 2
// deferred x: 1

