package main

import (
	"errors"
	"fmt"
)

// Notifier 是小接口：调用方只依赖它需要的能力。
type Notifier interface {
	Notify(msg string) error
}

// LogNotifier 是最小实现，生产环境可替换成邮件或短信。
type LogNotifier struct{ prefix string }

func (n LogNotifier) Notify(msg string) error {
	if msg == "" {
		return errors.New("empty message")
	}
	fmt.Println("["+n.prefix+"]", msg)
	return nil
}

// Service 用组合持有一个接口，而不是嵌入具体实现。
type Service struct {
	name string
	n    Notifier
}

func NewService(name string, n Notifier) *Service {
	return &Service{name: name, n: n}
}

func (s *Service) DoWork(task string) error {
	if err := s.n.Notify(s.name + ": " + task); err != nil {
		return fmt.Errorf("notify %q: %w", task, err)
	}
	return nil
}

// Audit 嵌入 LogNotifier：Notify 被提升，Audit 也满足 Notifier。
type Audit struct {
	LogNotifier
	Count int
}

func main() {
	svc := NewService("billing", LogNotifier{prefix: "info"})
	if err := svc.DoWork("charge order 42"); err != nil {
		fmt.Println("failed:", err)
	}

	a := Audit{LogNotifier: LogNotifier{prefix: "audit"}}
	var n Notifier = a
	_ = n.Notify("login")
	fmt.Println("count:", a.Count)

	var empty Notifier
	fmt.Println("nil interface:", empty == nil) // true

	var p *LogNotifier
	empty = p
	fmt.Println("typed nil:", empty == nil) // false：接口里是 (*LogNotifier, nil)
}

// 预期输出：
// [info] billing: charge order 42
// [audit] login
// count: 0
// nil interface: true
// typed nil: false

