package main

import (
	"context"
	"errors"
	"fmt"
	"time"
)

type traceKey struct{}

// fetch 模拟一次可能超时的下游调用：它必须尊重 ctx。
func fetch(ctx context.Context, id int) (string, error) {
	select {
	case <-time.After(80 * time.Millisecond): // 模拟慢下游
		return fmt.Sprintf("order-%d", id), nil
	case <-ctx.Done():
		return "", ctx.Err() // DeadlineExceeded 或 Canceled
	}
}

func handle(ctx context.Context, id int) error {
	ctx, cancel := context.WithTimeout(ctx, 50*time.Millisecond)
	defer cancel() // 释放 timer，并把节点从父 ctx 摘除

	res, err := fetch(ctx, id)
	if err != nil {
		return fmt.Errorf("handle order %d: %w", id, err)
	}
	fmt.Println("ok:", res)
	return nil
}

func main() {
	// 请求作用域从入口传入，而不是在函数里新建 Background。
	reqCtx, cancelReq := context.WithCancel(context.Background())
	defer cancelReq()

	if err := handle(reqCtx, 7); err != nil {
		fmt.Println("err:", err)
		fmt.Println("is timeout:", errors.Is(err, context.DeadlineExceeded))
	}

	// 父 ctx 10ms 后被主动取消，会打断子 ctx 原本 50ms 的预算。
	parent, cancelParent := context.WithCancel(context.Background())
	defer cancelParent()
	time.AfterFunc(10*time.Millisecond, cancelParent)
	if err := handle(parent, 8); err != nil {
		fmt.Println("err2:", err)
		fmt.Println("is canceled:", errors.Is(err, context.Canceled))
	}

	// WithValue 只放请求域数据（如 trace id），不放业务可选参数。
	ctxV := context.WithValue(context.Background(), traceKey{}, "trace-abc")
	fmt.Println("trace:", ctxV.Value(traceKey{}))
}

// 预期输出：
// err: handle order 7: context deadline exceeded
// is timeout: true
// err2: handle order 8: context canceled
// is canceled: true
// trace: trace-abc

