// pool_test.go：与同包实现放在一起，运行 go test -race -bench . -benchmem
package pool

import (
	"sync"
	"testing"
)

// startWorkers 启动 n 个 worker。Add 必须在 go 之前，否则 Wait 可能提前返回。
func startWorkers(n int, jobs <-chan int, results chan<- int, wg *sync.WaitGroup) {
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs {
				results <- j * j
			}
		}()
	}
}

// runPool 返回 1..tasks 的平方，顺序不保证。
func runPool(workers, tasks int) []int {
	jobs := make(chan int)
	results := make(chan int)
	var wg sync.WaitGroup

	startWorkers(workers, jobs, results, &wg)

	go func() {
		for i := 1; i <= tasks; i++ {
			jobs <- i
		}
		close(jobs) // 只有生产者关闭 jobs
	}()

	go func() {
		wg.Wait()
		close(results) // 所有 worker 退出后才能关闭 results
	}()

	out := make([]int, 0, tasks)
	for r := range results {
		out = append(out, r)
	}
	return out
}

func TestRunPool(t *testing.T) {
	got := runPool(3, 5)
	if len(got) != 5 {
		t.Fatalf("want 5 results, got %d: %v", len(got), got)
	}
	sum := 0
	for _, v := range got {
		sum += v
	}
	if sum != 55 { // 1+4+9+16+25
		t.Fatalf("want sum 55, got %d (%v)", sum, got)
	}
}

func TestRunPoolTable(t *testing.T) {
	cases := []struct {
		name    string
		workers int
		tasks   int
		wantSum int
	}{
		{"single", 1, 3, 14},
		{"workers-more-than-tasks", 8, 4, 30},
		{"many", 4, 10, 385},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := runPool(tc.workers, tc.tasks)
			sum := 0
			for _, v := range got {
				sum += v
			}
			if sum != tc.wantSum {
				t.Fatalf("sum = %d, want %d", sum, tc.wantSum)
			}
		})
	}
}

func BenchmarkRunPool(b *testing.B) {
	for i := 0; i < b.N; i++ {
		runPool(4, 100)
	}
}

// 运行：go test -race -bench . -benchmem ./...

