// go.mod（项目根目录）：
//   module example.com/orderdb
//   go 1.22
//   require github.com/go-sql-driver/mysql v1.8.1
//
// 拉依赖：go get github.com/go-sql-driver/mysql@v1.8.1
//
// 建表（MySQL 8.0）：
//   CREATE TABLE accounts (id BIGINT PRIMARY KEY, balance BIGINT NOT NULL) ENGINE=InnoDB;
//   CREATE TABLE orders (
//     id BIGINT AUTO_INCREMENT PRIMARY KEY,
//     user_id BIGINT NOT NULL,
//     amount BIGINT NOT NULL,
//     note VARCHAR(255) NULL,
//     created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
//     KEY idx_user (user_id)
//   ) ENGINE=InnoDB;
package main

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"log"
	"os"
	"strings"
	"time"

	_ "github.com/go-sql-driver/mysql"
)

type Order struct {
	ID        int64
	UserID    int64
	Amount    int64
	Note      sql.NullString
	CreatedAt time.Time
}

type Store struct{ db *sql.DB }

func Open(dsn string) (*Store, error) {
	db, err := sql.Open("mysql", dsn)
	if err != nil {
		return nil, fmt.Errorf("open: %w", err)
	}
	// 池参数必须在第一次查询之前设好
	db.SetMaxOpenConns(20)
	db.SetMaxIdleConns(20)
	db.SetConnMaxLifetime(30 * time.Minute)
	db.SetConnMaxIdleTime(5 * time.Minute)

	ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
	defer cancel()
	if err := db.PingContext(ctx); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("ping: %w", err)
	}
	return &Store{db: db}, nil
}

func (s *Store) Close() error { return s.db.Close() }

// ListOrders 查某个用户的订单；NULL 用 NullString 接，rows 用到 EOF 自动关。
func (s *Store) ListOrders(ctx context.Context, userID int64, limit int) ([]Order, error) {
	const q = `SELECT id, user_id, amount, note, created_at
	             FROM orders WHERE user_id = ? ORDER BY id DESC LIMIT ?`
	rows, err := s.db.QueryContext(ctx, q, userID, limit)
	if err != nil {
		return nil, fmt.Errorf("query orders: %w", err)
	}
	defer rows.Close() // 提前 return 也能归还连接

	orders := make([]Order, 0, limit)
	for rows.Next() {
		var o Order
		if err := rows.Scan(&o.ID, &o.UserID, &o.Amount, &o.Note, &o.CreatedAt); err != nil {
			return nil, fmt.Errorf("scan order: %w", err)
		}
		orders = append(orders, o)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate orders: %w", err)
	}
	return orders, nil
}

// InsertOrder 演示可复用的预编译语句；note 为 nil 时写入 SQL NULL。
func (s *Store) InsertOrder(ctx context.Context, userID, amount int64, note *string) (int64, error) {
	stmt, err := s.db.PrepareContext(ctx, `INSERT INTO orders(user_id, amount, note) VALUES (?, ?, ?)`)
	if err != nil {
		return 0, fmt.Errorf("prepare: %w", err)
	}
	defer stmt.Close()

	var n sql.NullString
	if note != nil {
		n = sql.NullString{String: *note, Valid: true}
	}
	res, err := stmt.ExecContext(ctx, userID, amount, n)
	if err != nil {
		return 0, fmt.Errorf("insert order: %w", err)
	}
	return res.LastInsertId()
}

// inTx 把 Begin/Commit/Rollback 收在一处，fn 里的所有语句都必须用 tx。
func (s *Store) inTx(ctx context.Context, fn func(context.Context, *sql.Tx) error) error {
	tx, err := s.db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelReadCommitted})
	if err != nil {
		return fmt.Errorf("begin: %w", err)
	}
	defer func() { _ = tx.Rollback() }() // Commit 后返回 ErrTxDone，可安全忽略

	if err := fn(ctx, tx); err != nil {
		return err
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("commit: %w", err)
	}
	return nil
}

// Transfer 按 id 升序锁两行，避免反向转账互相等待。
func (s *Store) Transfer(ctx context.Context, from, to, cents int64) error {
	if cents <= 0 {
		return errors.New("amount must be positive")
	}
	if from == to {
		return errors.New("from and to must differ")
	}
	ctx, cancel := context.WithTimeout(ctx, 3*time.Second)
	defer cancel()

	return s.inTx(ctx, func(ctx context.Context, tx *sql.Tx) error {
		low, high := from, to
		if low > high {
			low, high = high, low
		}
		for _, id := range []int64{low, high} {
			var got int64
			if err := tx.QueryRowContext(ctx,
				`SELECT id FROM accounts WHERE id = ? FOR UPDATE`, id).Scan(&got); err != nil {
				if errors.Is(err, sql.ErrNoRows) {
					return fmt.Errorf("account %d not found", id)
				}
				return fmt.Errorf("lock account %d: %w", id, err)
			}
		}

		var balance int64
		if err := tx.QueryRowContext(ctx,
			`SELECT balance FROM accounts WHERE id = ?`, from).Scan(&balance); err != nil {
			return fmt.Errorf("load balance: %w", err)
		}
		if balance < cents {
			return fmt.Errorf("insufficient balance: have %d, need %d", balance, cents)
		}

		if _, err := tx.ExecContext(ctx,
			`UPDATE accounts SET balance = balance - ? WHERE id = ?`, cents, from); err != nil {
			return fmt.Errorf("debit: %w", err)
		}
		if _, err := tx.ExecContext(ctx,
			`UPDATE accounts SET balance = balance + ? WHERE id = ?`, cents, to); err != nil {
			return fmt.Errorf("credit: %w", err)
		}
		return nil
	})
}

// OrdersByUsers 用一条 IN 查询消掉 N+1。
func (s *Store) OrdersByUsers(ctx context.Context, userIDs []int64) (map[int64][]Order, error) {
	out := make(map[int64][]Order, len(userIDs))
	if len(userIDs) == 0 {
		return out, nil
	}
	marks := make([]string, len(userIDs))
	args := make([]any, len(userIDs))
	for i, id := range userIDs {
		marks[i] = "?"
		args[i] = id
	}
	q := `SELECT id, user_id, amount, note, created_at FROM orders WHERE user_id IN (` +
		strings.Join(marks, ",") + `) ORDER BY id`

	rows, err := s.db.QueryContext(ctx, q, args...)
	if err != nil {
		return nil, fmt.Errorf("query orders by users: %w", err)
	}
	defer rows.Close()

	for rows.Next() {
		var o Order
		if err := rows.Scan(&o.ID, &o.UserID, &o.Amount, &o.Note, &o.CreatedAt); err != nil {
			return nil, fmt.Errorf("scan order: %w", err)
		}
		out[o.UserID] = append(out[o.UserID], o)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate orders: %w", err)
	}
	return out, nil
}

func main() {
	dsn := os.Getenv("MYSQL_DSN")
	if dsn == "" {
		log.Fatal("MYSQL_DSN is required, e.g. root:root@tcp(127.0.0.1:3306)/demo?parseTime=true")
	}
	store, err := Open(dsn)
	if err != nil {
		log.Fatalf("open db: %v", err)
	}
	defer store.Close()

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	orders, err := store.ListOrders(ctx, 1, 20)
	if err != nil {
		log.Fatalf("list orders: %v", err)
	}
	for _, o := range orders {
		note := "-"
		if o.Note.Valid {
			note = o.Note.String
		}
		fmt.Printf("order=%d user=%d amount=%d note=%s at=%s\n",
			o.ID, o.UserID, o.Amount, note, o.CreatedAt.Format(time.RFC3339))
	}

	st := store.db.Stats()
	fmt.Printf("pool max=%d open=%d inuse=%d idle=%d wait=%d\n",
		st.MaxOpenConnections, st.OpenConnections, st.InUse, st.Idle, st.WaitCount)
}

