// go.mod（项目根目录）：
//   module example.com/lifecycle
//   go 1.22
// 全部使用标准库（log/slog 自 Go 1.21 起进入标准库），不需要 go get。
package main

import (
	"context"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"sync/atomic"
	"syscall"
	"time"
)

type Config struct {
	Addr            string
	LogLevel        string
	Env             string
	ShutdownTimeout time.Duration
	ConfigPath      string
}

type fileConfig struct {
	Addr        string `json:"addr"`
	LogLevel    string `json:"log_level"`
	Env         string `json:"env"`
	ShutdownSec int    `json:"shutdown_seconds"`
}

// LoadConfig 实现四层优先级：默认值 < 文件 < 环境变量 < 显式 flag。
func LoadConfig(args []string) (Config, error) {
	cfg := Config{
		Addr:            ":8080",
		LogLevel:        "info",
		Env:             "dev",
		ShutdownTimeout: 10 * time.Second,
	}

	fs := flag.NewFlagSet("order-api", flag.ContinueOnError)
	addr := fs.String("addr", "", "监听地址，例如 :8080")
	level := fs.String("log-level", "", "debug|info|warn|error")
	env := fs.String("env", "", "dev|staging|prod")
	shutdownSec := fs.Int("shutdown-seconds", 0, "优雅退出最长等待秒数")
	cfgPath := fs.String("config", "", "JSON 配置文件路径")
	if err := fs.Parse(args); err != nil {
		return cfg, err
	}
	cfg.ConfigPath = *cfgPath

	// 第二层：文件只覆盖它显式给出的字段
	if *cfgPath != "" {
		raw, err := os.ReadFile(*cfgPath)
		if err != nil {
			return cfg, fmt.Errorf("read config: %w", err)
		}
		var fc fileConfig
		if err := json.Unmarshal(raw, &fc); err != nil {
			return cfg, fmt.Errorf("parse config: %w", err)
		}
		if fc.Addr != "" {
			cfg.Addr = fc.Addr
		}
		if fc.LogLevel != "" {
			cfg.LogLevel = fc.LogLevel
		}
		if fc.Env != "" {
			cfg.Env = fc.Env
		}
		if fc.ShutdownSec > 0 {
			cfg.ShutdownTimeout = time.Duration(fc.ShutdownSec) * time.Second
		}
	}

	// 第三层：部署环境注入的变量
	if v := os.Getenv("APP_ADDR"); v != "" {
		cfg.Addr = v
	}
	if v := os.Getenv("APP_LOG_LEVEL"); v != "" {
		cfg.LogLevel = v
	}
	if v := os.Getenv("APP_ENV"); v != "" {
		cfg.Env = v
	}
	if v := os.Getenv("APP_SHUTDOWN_SECONDS"); v != "" {
		n, err := strconv.Atoi(v)
		if err != nil || n <= 0 {
			return cfg, fmt.Errorf("APP_SHUTDOWN_SECONDS must be positive, got %q", v)
		}
		cfg.ShutdownTimeout = time.Duration(n) * time.Second
	}

	// 第四层：只有真正传了的 flag 才覆盖前面的值
	set := map[string]bool{}
	fs.Visit(func(f *flag.Flag) { set[f.Name] = true })
	if set["addr"] {
		cfg.Addr = *addr
	}
	if set["log-level"] {
		cfg.LogLevel = *level
	}
	if set["env"] {
		cfg.Env = *env
	}
	if set["shutdown-seconds"] {
		cfg.ShutdownTimeout = time.Duration(*shutdownSec) * time.Second
	}

	return cfg, cfg.validate()
}

func (c Config) validate() error {
	if c.Addr == "" {
		return errors.New("addr must not be empty")
	}
	if c.ShutdownTimeout <= 0 {
		return errors.New("shutdown timeout must be positive")
	}
	return nil
}

// reloadLogLevel 只从配置文件里取 log_level，其它字段一律忽略。
func reloadLogLevel(path string) (string, error) {
	raw, err := os.ReadFile(path)
	if err != nil {
		return "", err
	}
	var fc fileConfig
	if err := json.Unmarshal(raw, &fc); err != nil {
		return "", err
	}
	return fc.LogLevel, nil
}

// newLogger 返回 logger 和 LevelVar，后者留给 SIGHUP 热更新使用。
func newLogger(level, env string) (*slog.Logger, *slog.LevelVar, error) {
	lv := new(slog.LevelVar)
	if err := lv.UnmarshalText([]byte(level)); err != nil {
		return nil, nil, fmt.Errorf("invalid log level %q: %w", level, err)
	}
	opts := &slog.HandlerOptions{Level: lv}
	var h slog.Handler
	if env == "dev" {
		h = slog.NewTextHandler(os.Stdout, opts)
	} else {
		h = slog.NewJSONHandler(os.Stdout, opts)
	}
	return slog.New(h).With("service", "order-api", "env", env), lv, nil
}

type App struct {
	log   *slog.Logger
	ready *atomic.Bool
}

func (a *App) routes() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ok"))
	})
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
		if !a.ready.Load() {
			http.Error(w, "warming up", http.StatusServiceUnavailable)
			return
		}
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ready"))
	})
	mux.HandleFunc("GET /api/ping", func(w http.ResponseWriter, r *http.Request) {
		a.log.InfoContext(r.Context(), "ping", "rid", r.Header.Get("X-Request-Id"))
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"pong":true}`))
	})
	return mux
}

// startWorker 模拟后台任务：只能通过 ctx 取消，主流程用 done 等它退出。
func startWorker(ctx context.Context, log *slog.Logger) <-chan struct{} {
	done := make(chan struct{})
	go func() {
		defer close(done)
		t := time.NewTicker(2 * time.Second)
		defer t.Stop()
		for {
			select {
			case <-ctx.Done():
				log.Info("worker stopped")
				return
			case <-t.C:
				log.Debug("worker tick")
			}
		}
	}()
	return done
}

func run() error {
	cfg, err := LoadConfig(os.Args[1:])
	if err != nil {
		return err
	}

	logger, lv, err := newLogger(cfg.LogLevel, cfg.Env)
	if err != nil {
		return err
	}
	slog.SetDefault(logger)

	// 启动顺序：配置 → 日志 → 监听 → 后台任务 → ready
	ln, err := net.Listen("tcp", cfg.Addr)
	if err != nil {
		return fmt.Errorf("listen %s: %w", cfg.Addr, err)
	}

	app := &App{log: logger, ready: new(atomic.Bool)}
	srv := &http.Server{
		Handler:           app.routes(),
		ReadHeaderTimeout: 3 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
		ErrorLog:          slog.NewLogLogger(logger.Handler(), slog.LevelWarn),
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	go func() {
		<-ctx.Done()
		stop() // 恢复默认行为，drain 卡住时第二次 Ctrl+C 可强杀
	}()

	workerCtx, cancelWorker := context.WithCancel(context.Background())
	workerDone := startWorker(workerCtx, logger)

	// 只对日志级别做热更新：收到 SIGHUP 重读配置文件，其它字段忽略
	hup := make(chan os.Signal, 1)
	signal.Notify(hup, syscall.SIGHUP)
	defer signal.Stop(hup)
	go func() {
		for {
			select {
			case <-ctx.Done():
				return
			case <-hup:
				if cfg.ConfigPath == "" {
					logger.Warn("SIGHUP ignored: start with -config to enable reload")
					continue
				}
				level, err := reloadLogLevel(cfg.ConfigPath)
				if err != nil {
					logger.Error("reload config failed", "err", err)
					continue
				}
				if level == "" {
					logger.Warn("SIGHUP ignored: log_level is empty")
					continue
				}
				if err := lv.UnmarshalText([]byte(level)); err != nil {
					logger.Error("reload log level failed", "err", err)
					continue
				}
				logger.Info("log level reloaded", "level", level)
			}
		}
	}()

	serveErr := make(chan error, 1)
	go func() {
		logger.Info("http server listening", "addr", ln.Addr().String())
		serveErr <- srv.Serve(ln)
	}()

	// 模拟依赖预热：预热完成前 /readyz 必须是 503
	go func() {
		time.Sleep(300 * time.Millisecond)
		app.ready.Store(true)
		logger.Info("readiness turned on")
	}()

	select {
	case err := <-serveErr:
		cancelWorker()
		<-workerDone
		return fmt.Errorf("serve: %w", err)
	case <-ctx.Done():
		logger.Info("signal received, start draining", "timeout", cfg.ShutdownTimeout)
	}

	// 关闭顺序与启动相反：先摘 ready，再停新请求，再停后台，最后关资源
	app.ready.Store(false)
	shutdownCtx, cancel := context.WithTimeout(context.Background(), cfg.ShutdownTimeout)
	defer cancel()

	shutdownErr := srv.Shutdown(shutdownCtx)
	cancelWorker()
	<-workerDone

	if shutdownErr != nil {
		logger.Error("graceful shutdown failed, forcing close", "err", shutdownErr)
		_ = srv.Close()
		return shutdownErr
	}
	logger.Info("shutdown complete")
	return nil
}

func main() {
	if err := run(); err != nil {
		slog.Error("fatal", "err", err)
		os.Exit(1)
	}
}

