// pproflab/main.go —— Go 1.22，只用标准库，无第三方依赖
//
// 准备：
//   go mod init pproflab
//
// 只跑基准对比（不起服务，约 2 秒；rows 越大差异越明显）：
//   go run . -bench -rows 200
//
// 起服务（业务路由与 pprof 同一端口）：
//   go run . -rows 200
//
// 抓 10 秒 CPU profile，看前 15 名：
//   go tool pprof -top -nodecount=15 "http://127.0.0.1:6060/debug/pprof/profile?seconds=10"
//
// 读火焰图（浏览器打开 http://127.0.0.1:8081）：
//   go tool pprof -http=:8081 cpu.pprof
//
// 找分配最凶的函数，并摊到源码行：
//   go tool pprof -sample_index=alloc_space -list=buildNaive mem.pprof
//
// 找存活对象（判断泄漏才用这个视图，务必带 ?gc=1）：
//   go tool pprof -sample_index=inuse_space -top mem.pprof
//
// 逃逸判定（PowerShell 用 Select-String 过滤，bash 用 grep）：
//   go build -gcflags="-m -m" . 2>&1 | Select-String "escapes|moved to heap"
//
// 预期（数值随机器不同，只看量级关系）：
//   rows=200 时 concat 的 B/op 是 builder 的数倍，allocs/op 差两个数量级（几百比个位数）；
//   rows 翻四倍，concat 的 B/op 大致翻十几倍，builder 只线性增长。

package main

import (
	"flag"
	"fmt"
	"io"
	"log"
	"net/http"
	pprofhttp "net/http/pprof" // 与 runtime/pprof 同名，必须起别名
	"os"
	"runtime"
	"runtime/pprof"
	"strconv"
	"strings"
	"testing"
	"time"
)

// Row 用值类型而不是指针：切片里连续存放，遍历时缓存友好。
type Row struct {
	ID   int
	Name string
	Qty  int
}

// sink 防止编译器把「结果没人用」的调用整段删掉（dead code elimination）。
var sink string

// buildNaive：每轮都新建字符串并把旧内容整体拷贝一次，总拷贝量 O(n^2)。
func buildNaive(rows []Row) string {
	out := ""
	for _, r := range rows {
		out += fmt.Sprintf("%d,%s,%d\n", r.ID, r.Name, r.Qty)
	}
	return out
}

// buildBuilder：预分配一次缓冲，循环里只追加，最后才生成 string。
func buildBuilder(rows []Row) string {
	var b strings.Builder
	b.Grow(len(rows) * 16) // 每行约 16 字节，预留后扩容次数为 0
	for _, r := range rows {
		fmt.Fprintf(&b, "%d,%s,%d\n", r.ID, r.Name, r.Qty)
	}
	return b.String()
}

// makeRows 造数据；Name 用短串，让差异集中在拼接而不是数据生成上。
func makeRows(n int) []Row {
	rows := make([]Row, 0, n)
	for i := 0; i < n; i++ {
		rows = append(rows, Row{ID: i, Name: "sku-" + strconv.Itoa(i%97), Qty: i % 13})
	}
	return rows
}

// runBench 用 testing.Benchmark 在普通程序里跑基准，省掉 _test.go。
func runBench(rows int) {
	data := makeRows(rows)
	cases := []struct {
		name string
		fn   func([]Row) string
	}{
		{"concat", buildNaive},
		{"builder", buildBuilder},
	}
	fmt.Printf("rows=%d\n", rows)
	for _, c := range cases {
		fn := c.fn
		res := testing.Benchmark(func(b *testing.B) {
			b.ReportAllocs() // 不调用则 B/op、allocs/op 恒为 0
			for i := 0; i < b.N; i++ {
				sink = fn(data)
			}
		})
		fmt.Printf("  %-8s %10d ns/op %10d B/op %6d allocs/op\n",
			c.name, res.NsPerOp(), res.AllocedBytesPerOp(), res.AllocsPerOp())
	}
}

// profile 在 seconds 秒内持续制造 CPU 负载，并写出 cpu.pprof 与 mem.pprof。
func profile(seconds int, cpuPath, memPath string) error {
	cf, err := os.Create(cpuPath)
	if err != nil {
		return fmt.Errorf("create %s: %w", cpuPath, err)
	}
	if err := pprof.StartCPUProfile(cf); err != nil {
		cf.Close()
		return fmt.Errorf("start cpu profile: %w", err)
	}
	// pprof 是 100Hz 采样：这段时间必须有活干，否则采到的全是空闲栈
	data := makeRows(500)
	deadline := time.Now().Add(time.Duration(seconds) * time.Second)
	for time.Now().Before(deadline) {
		sink = buildNaive(data)
	}
	pprof.StopCPUProfile()
	if err := cf.Close(); err != nil { // 先 Stop 再 Close，否则尾部数据丢失
		return fmt.Errorf("close %s: %w", cpuPath, err)
	}

	mf, err := os.Create(memPath)
	if err != nil {
		return fmt.Errorf("create %s: %w", memPath, err)
	}
	defer mf.Close()
	runtime.GC() // 先清垃圾，inuse_space 才代表「活着的那部分」
	return pprof.WriteHeapProfile(mf)
}

func main() {
	var (
		bench = flag.Bool("bench", false, "只跑基准对比，不起服务")
		rows  = flag.Int("rows", 200, "每次请求生成的行数")
		secs  = flag.Int("cpu", 5, "CPU profile 采样秒数")
		addr  = flag.String("addr", "127.0.0.1:6060", "pprof 与业务共用端口")
		naive = flag.Bool("naive", false, "用 += 拼接（默认 Builder）")
	)
	flag.Parse()

	if *bench {
		runBench(*rows)
		return
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/report", func(w http.ResponseWriter, r *http.Request) {
		data := makeRows(*rows)
		var out string
		if *naive {
			out = buildNaive(data)
		} else {
			out = buildBuilder(data)
		}
		w.Header().Set("Content-Type", "text/csv; charset=utf-8")
		_, _ = io.WriteString(w, out)
	})

	// 显式挂载 pprof：空白 import 会把它注册到 DefaultServeMux，容易在生产端口裸奔
	mux.HandleFunc("/debug/pprof/", pprofhttp.Index)
	mux.HandleFunc("/debug/pprof/cmdline", pprofhttp.Cmdline)
	mux.HandleFunc("/debug/pprof/profile", pprofhttp.Profile)
	mux.HandleFunc("/debug/pprof/symbol", pprofhttp.Symbol)
	mux.HandleFunc("/debug/pprof/trace", pprofhttp.Trace)
	mux.Handle("/debug/pprof/goroutine", pprofhttp.Handler("goroutine"))
	mux.Handle("/debug/pprof/heap", pprofhttp.Handler("heap"))
	mux.Handle("/debug/pprof/allocs", pprofhttp.Handler("allocs"))
	mux.Handle("/debug/pprof/block", pprofhttp.Handler("block"))
	mux.Handle("/debug/pprof/mutex", pprofhttp.Handler("mutex"))

	srv := &http.Server{
		Addr:              *addr,
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second, // 慢速请求头攻击的兜底
	}
	go func() {
		log.Printf("listen %s | GET /report | GET /debug/pprof/", *addr)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Printf("server: %v", err)
		}
	}()

	if err := profile(*secs, "cpu.pprof", "mem.pprof"); err != nil {
		log.Fatalf("profile: %v", err)
	}
	fmt.Println("written cpu.pprof mem.pprof")
	fmt.Println("next: go tool pprof -http=:8081 cpu.pprof")
}

