// genericsreflect/main.go —— Go 1.22，只用标准库，无第三方依赖
//
// 准备：
//   go mod init genericsreflect
//
// 运行（打印泛型结果 + 反射与手写的基准对比）：
//   go run .
//
// 看逃逸判定（bash 用 grep 代替 Select-String）：
//   go build -gcflags="-m -m" . 2>&1 | Select-String "escapes|moved to heap"
//
// 预期（数值随机器不同，量级关系稳定）：
//   sum(int)     = 10
//   sum(Celsius) = 36.5
//   map(len)     = 3
//   decode       = {Host:127.0.0.1 Port:8080 Debug:true note:}
//   FieldByName  : 字段 "Hostname" 不存在
//   reflect decode     2200 ns/op   1248 B/op  36 allocs/op
//   manual  decode      110 ns/op      0 B/op   0 allocs/op

package main

import (
	"fmt"
	"reflect"
	"strconv"
	"testing"
)

type Celsius float64

type Row struct {
	ID   int
	Name string
}

// Number 是类型集合：~ 表示底层类型是其中之一，所以具名类型 Celsius 也能用。
type Number interface {
	~int | ~int64 | ~float64
}

// Sum 用类型参数替代 []any + 断言：调用点保留静态类型，值不装箱。
func Sum[T Number](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

// Map 的 E、R 都能从实参推断，调用时不必写 Map[int, string]。
func Map[E, R any](in []E, fn func(E) R) []R {
	out := make([]R, 0, len(in))
	for _, v := range in {
		out = append(out, fn(v))
	}
	return out
}

// Env 用 tag 声明配置键；note 未导出，用来演示 CanSet 恒为 false 的字段。
type Env struct {
	Host  string `env:"HOST"`
	Port  int    `env:"PORT"`
	Debug bool   `env:"DEBUG"`
	note  string
}

// Decode 是反射版：每次调用都重新遍历字段、重新解析 tag。
func Decode(dst any, lookup func(string) (string, bool)) error {
	rv := reflect.ValueOf(dst)
	if rv.Kind() != reflect.Pointer || rv.IsNil() {
		return fmt.Errorf("decode: 需要非 nil 指针，得到 %T", dst)
	}
	rv = rv.Elem() // 必须 Elem 才可寻址，才能 Set
	if rv.Kind() != reflect.Struct {
		return fmt.Errorf("decode: 需要指向结构体的指针，得到 %s", rv.Kind())
	}
	rt := rv.Type()
	for i := 0; i < rt.NumField(); i++ {
		sf := rt.Field(i)
		if !sf.IsExported() {
			continue // 未导出字段 CanSet 恒为 false，跳过而不是 panic
		}
		key := sf.Tag.Get("env")
		if key == "-" {
			continue
		}
		if key == "" {
			key = sf.Name
		}
		raw, ok := lookup(key)
		if !ok {
			continue
		}
		fv := rv.Field(i)
		if !fv.CanSet() {
			continue
		}
		switch fv.Kind() {
		case reflect.String:
			fv.SetString(raw)
		case reflect.Int:
			n, err := strconv.Atoi(raw)
			if err != nil {
				return fmt.Errorf("字段 %s: %w", sf.Name, err)
			}
			fv.SetInt(int64(n))
		case reflect.Bool:
			b, err := strconv.ParseBool(raw)
			if err != nil {
				return fmt.Errorf("字段 %s: %w", sf.Name, err)
			}
			fv.SetBool(b)
		default:
			return fmt.Errorf("字段 %s: 不支持的类型 %s", sf.Name, fv.Kind())
		}
	}
	return nil
}

// decodeManual 手写版：字段固定、编译期检查、零反射零分配。
func decodeManual(dst *Env, lookup func(string) (string, bool)) error {
	if v, ok := lookup("HOST"); ok {
		dst.Host = v
	}
	if v, ok := lookup("PORT"); ok {
		n, err := strconv.Atoi(v)
		if err != nil {
			return fmt.Errorf("PORT: %w", err)
		}
		dst.Port = n
	}
	if v, ok := lookup("DEBUG"); ok {
		b, err := strconv.ParseBool(v)
		if err != nil {
			return fmt.Errorf("DEBUG: %w", err)
		}
		dst.Debug = b
	}
	return nil
}

// fieldByName 演示 FieldByName 找不到字段时返回 zero Value。
func fieldByName(v any, name string) (string, error) {
	rv := reflect.ValueOf(v)
	if rv.Kind() != reflect.Pointer || rv.IsNil() {
		return "", fmt.Errorf("fieldByName: 需要非 nil 指针")
	}
	f := rv.Elem().FieldByName(name)
	if !f.IsValid() { // zero Value 上调用 Interface() 会 panic
		return "", fmt.Errorf("字段 %q 不存在", name)
	}
	return fmt.Sprintf("%v", f.Interface()), nil
}

// lookupFrom 把 map 包成查表函数，两种解码共用同一份数据源。
func lookupFrom(m map[string]string) func(string) (string, bool) {
	return func(k string) (string, bool) {
		v, ok := m[k]
		return v, ok
	}
}

func envMap() map[string]string {
	return map[string]string{"HOST": "127.0.0.1", "PORT": "8080", "DEBUG": "true"}
}

// sinkEnv 防止基准里的结果被当作死代码优化掉。
var sinkEnv Env

func main() {
	// 1) 泛型：同一份 Sum 同时服务 int 与具名类型 Celsius
	fmt.Println("sum(int)     =", Sum([]int{1, 2, 3, 4}))
	fmt.Println("sum(Celsius) =", Sum([]Celsius{18.5, 18.0}))
	names := Map([]Row{{1, "a"}, {2, "b"}, {3, "c"}}, func(r Row) string { return r.Name })
	fmt.Println("map(len)     =", len(names))

	// 2) 反射解码：必须传指针，否则 Set 直接 panic
	var env Env
	if err := Decode(&env, lookupFrom(envMap())); err != nil {
		fmt.Println("decode error:", err)
		return
	}
	fmt.Printf("decode       = %+v\n", env)

	// 3) 字段名拼错不会 panic，IsValid 会告诉你结果是零值
	if v, err := fieldByName(&env, "Hostname"); err != nil {
		fmt.Println("FieldByName  :", err)
	} else {
		fmt.Println("FieldByName  :", v)
	}

	// 4) 同一份数据，反射与手写各跑一次基准
	lookup := lookupFrom(envMap())
	resReflect := testing.Benchmark(func(b *testing.B) {
		b.ReportAllocs()
		for i := 0; i < b.N; i++ {
			var e Env
			if err := Decode(&e, lookup); err != nil {
				b.Fatal(err)
			}
			sinkEnv = e
		}
	})
	resManual := testing.Benchmark(func(b *testing.B) {
		b.ReportAllocs()
		for i := 0; i < b.N; i++ {
			var e Env
			if err := decodeManual(&e, lookup); err != nil {
				b.Fatal(err)
			}
			sinkEnv = e
		}
	})
	fmt.Printf("reflect decode %8d ns/op %6d B/op %3d allocs/op\n",
		resReflect.NsPerOp(), resReflect.AllocedBytesPerOp(), resReflect.AllocsPerOp())
	fmt.Printf("manual  decode %8d ns/op %6d B/op %3d allocs/op\n",
		resManual.NsPerOp(), resManual.AllocedBytesPerOp(), resManual.AllocsPerOp())
}

