// prodlab/main.go —— Go 1.22，只用标准库，无第三方依赖
//
// 准备：
//   go mod init prodlab
//
// 运行（业务、pprof、/metrics 共用 127.0.0.1:6060）：
//   go run .
//
// 制造 goroutine 泄漏（bash）：
//   for i in $(seq 20); do curl -s localhost:6060/leak; done
// 制造 goroutine 泄漏（PowerShell）：
//   1..20 | ForEach-Object { curl.exe -s http://127.0.0.1:6060/leak }
//
// 看指标：
//   curl -s http://127.0.0.1:6060/metrics | Select-String goroutines
//
// 聚合栈（同一栈帧只出现一次，前面带数量）：
//   curl -s "http://127.0.0.1:6060/debug/pprof/goroutine?debug=1"
//
// 全量栈（每个 goroutine 一段，量大，务必重定向到文件）：
//   curl -s "http://127.0.0.1:6060/debug/pprof/goroutine?debug=2" > g.txt
//
// 堆（?gc=1 先做一次 GC，inuse_space 才是存活量）：
//   go tool pprof -sample_index=inuse_space -http=:8081 "http://127.0.0.1:6060/debug/pprof/heap?gc=1"
//
// 预期：
//   每调一次 /leak，日志里的 goroutines 加一，rising 连续三次后 dump 出 goroutine-<时分秒>.txt；
//   /metrics 的 prodlab_goroutine_leaks 同步上涨，go_runtime_gc_heap_live_bytes 随 /work 上涨。

package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	pprofhttp "net/http/pprof"
	"os"
	"os/signal"
	"runtime"
	"runtime/metrics"
	"runtime/pprof"
	"strings"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

var (
	leaks      atomic.Int64
	cacheBytes atomic.Int64
	cache      sync.Map // 只写不删，模拟「缓存没有淘汰策略」
)

// metricNames 只挑排障最常用的几个；名字在 Go 1.19+ 稳定，但运行期仍要校验。
var metricNames = []string{
	"/sched/goroutines:goroutines",
	"/memory/classes/heap/objects:bytes",
	"/memory/classes/heap/unused:bytes",
	"/memory/classes/heap/free:bytes",
	"/memory/classes/total:bytes",
	"/gc/heap/allocs:bytes",
	"/gc/heap/frees:bytes",
	"/gc/heap/live:bytes",
	"/gc/cycles/total:gc-cycles",
	"/gc/gomemlimit:bytes",
	"/gc/gogc:percent",
}

// readMetrics 先对着 metrics.All() 校验名字：metrics.Read 遇到未知名字会 panic，
// 而不同 Go 版本的指标集合略有差异，监控探针不能因此整片挂掉。
func readMetrics() []metrics.Sample {
	known := make(map[string]struct{}, len(metricNames))
	for _, d := range metrics.All() {
		known[d.Name] = struct{}{}
	}
	samples := make([]metrics.Sample, 0, len(metricNames))
	for _, name := range metricNames {
		if _, ok := known[name]; !ok {
			slog.Warn("metric 名字不存在，已跳过", "name", name, "go", runtime.Version())
			continue
		}
		samples = append(samples, metrics.Sample{Name: name})
	}
	metrics.Read(samples)
	return samples
}

// metricName 把 /gc/heap/live:bytes 转成 go_runtime_gc_heap_live_bytes。
func metricName(full string) string {
	s := strings.TrimPrefix(full, "/")
	s = strings.ReplaceAll(s, "/", "_")
	s = strings.Replace(s, ":", "_", 1)
	s = strings.ReplaceAll(s, "-", "_")
	return "go_runtime_" + s
}

// metricsHandler 手写 Prometheus 文本格式，省掉为了一个 /metrics 引入依赖。
func metricsHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/plain; version=0.0.4; charset=utf-8")
	var b strings.Builder
	b.WriteString("# TYPE go_runtime_goroutines gauge\n")
	fmt.Fprintf(&b, "go_runtime_goroutines %d\n", runtime.NumGoroutine())
	b.WriteString("# TYPE prodlab_goroutine_leaks counter\n")
	fmt.Fprintf(&b, "prodlab_goroutine_leaks %d\n", leaks.Load())
	b.WriteString("# TYPE prodlab_cache_bytes gauge\n")
	fmt.Fprintf(&b, "prodlab_cache_bytes %d\n", cacheBytes.Load())
	for _, s := range readMetrics() {
		switch s.Value.Kind() {
		case metrics.KindUint64:
			fmt.Fprintf(&b, "%s %d\n", metricName(s.Name), s.Value.Uint64())
		case metrics.KindFloat64:
			fmt.Fprintf(&b, "%s %g\n", metricName(s.Name), s.Value.Float64())
		default:
			continue // 直方图类指标不能当 gauge 打，直接跳过
		}
	}
	_, _ = io.WriteString(w, b.String())
}

// leakHandler 模拟「每个请求起一个后台 goroutine，但它永远等不到退出信号」。
func leakHandler(w http.ResponseWriter, r *http.Request) {
	stop := make(chan struct{}) // 没人 close、也没人写：下面的 goroutine 永久阻塞
	go func() {
		<-stop
	}()
	n := leaks.Add(1)
	w.WriteHeader(http.StatusAccepted)
	fmt.Fprintf(w, "leaked=%d\n", n)
}

// workHandler 每次塞 1MiB 进 cache 且从不删除，用来复现「RSS 单调上涨」。
func workHandler(w http.ResponseWriter, r *http.Request) {
	buf := make([]byte, 1<<20)
	for i := 0; i < len(buf); i += 512 {
		buf[i] = byte(i)
	}
	cache.Store(time.Now().UnixNano(), buf)
	total := cacheBytes.Add(int64(len(buf)))
	fmt.Fprintf(w, "stored=1MiB total=%dMiB\n", total>>20)
}

// withLogging 用结构化日志记录请求，request_id 是串起日志与链路的那个字段。
func withLogging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		id := r.Header.Get("X-Request-Id")
		if id == "" {
			id = fmt.Sprintf("req-%d", start.UnixNano())
		}
		w.Header().Set("X-Request-Id", id)
		next.ServeHTTP(w, r)
		slog.Info("http",
			"request_id", id,
			"method", r.Method,
			"path", r.URL.Path,
			"dur_ms", time.Since(start).Milliseconds(),
		)
	})
}

// dumpGoroutines 把全量栈写到文件：几万 goroutine 的栈是几十 MB，绝不能打进日志。
func dumpGoroutines(path string) error {
	f, err := os.Create(path)
	if err != nil {
		return err
	}
	defer f.Close()
	return pprof.Lookup("goroutine").WriteTo(f, 2) // 2 = 每个 goroutine 一段完整栈
}

// watchdog 每 interval 读一次 goroutine 数，连续三次上涨才 dump，避免正常波动天天告警。
func watchdog(ctx context.Context, interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	last, rising := 0, 0
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			n := runtime.NumGoroutine()
			if n > last {
				rising++
			} else {
				rising = 0
			}
			slog.Info("runtime", "goroutines", n, "rising", rising, "leaks", leaks.Load())
			if rising >= 3 {
				path := fmt.Sprintf("goroutine-%s.txt", time.Now().Format("150405"))
				if err := dumpGoroutines(path); err != nil {
					slog.Error("dump goroutines", "err", err)
				} else {
					slog.Warn("goroutine 持续上涨，已落盘", "path", path, "goroutines", n)
				}
				rising = 0
			}
			last = n
		}
	}
}

func main() {
	slog.SetDefault(slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo})))

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	mux := http.NewServeMux()
	mux.HandleFunc("/metrics", metricsHandler)
	mux.HandleFunc("/leak", leakHandler)
	mux.HandleFunc("/work", workHandler)
	// 显式挂 pprof，而不是 import _ "net/http/pprof" 把它注册到 DefaultServeMux
	mux.Handle("/debug/pprof/", http.HandlerFunc(pprofhttp.Index))
	mux.Handle("/debug/pprof/profile", http.HandlerFunc(pprofhttp.Profile))
	mux.Handle("/debug/pprof/goroutine", pprofhttp.Handler("goroutine"))
	mux.Handle("/debug/pprof/heap", pprofhttp.Handler("heap"))
	mux.Handle("/debug/pprof/allocs", pprofhttp.Handler("allocs"))

	srv := &http.Server{
		Addr:              "127.0.0.1:6060",
		Handler:           withLogging(mux),
		ReadHeaderTimeout: 5 * time.Second,
	}

	go watchdog(ctx, 5*time.Second)
	go func() {
		slog.Info("listen", "addr", srv.Addr)
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			slog.Error("listen", "err", err)
			stop()
		}
	}()

	<-ctx.Done()
	slog.Info("shutdown", "reason", "signal")
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(shutdownCtx); err != nil {
		slog.Error("shutdown", "err", err)
	}
	slog.Info("bye", "leaks", leaks.Load(), "cache_mib", cacheBytes.Load()>>20)
}
